/**
 * Offline license validation using HMAC-SHA-256.
 * Codes are generated by the seller and validated locally without internet.
 *
 * Format: 8-digit number derived from HMAC (e.g. "04729651")
 */

const SECRET = import.meta.env.VITE_LICENSE_SECRET as string ?? 'BarOpt@2026#Kx9m-Pq3rVn8w-Zj5tYd'
const STORAGE_KEY = 'baropt-license'

// ── HMAC helpers ──────────────────────────────────────────────────────────────

async function hmacBytes(message: string): Promise<Uint8Array> {
  const enc = new TextEncoder()
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(SECRET),
    { name: 'HMAC', hash: 'SHA-256' },
    false, ['sign']
  )
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(message))
  return new Uint8Array(sig)
}

// ── Code generation ───────────────────────────────────────────────────────────

export async function generateLicenseCode(storeId: number): Promise<string> {
  const id = String(storeId).padStart(4, '0')
  const bytes = await hmacBytes(id)
  // First 4 bytes → uint32 → mod 100_000_000 → 8-digit string
  const num = ((bytes[0] << 24) | (bytes[1] << 16) | (bytes[2] << 8) | bytes[3]) >>> 0
  return String(num % 100_000_000).padStart(8, '0')
}

// ── Code validation ───────────────────────────────────────────────────────────

// Returns the storeId (1–9999) if the code is valid, or null if not.
export async function validateLicenseCode(input: string): Promise<number | null> {
  const clean = input.trim().replace(/\D/g, '')
  if (clean.length !== 8) return null

  // Check all store IDs 1–9999 in parallel
  const checks = Array.from({ length: 9999 }, (_, i) =>
    generateLicenseCode(i + 1).then(code => (code === clean ? i + 1 : 0))
  )
  const results = await Promise.all(checks)
  const found = results.find(r => r > 0) ?? null
  return found ?? null
}

// ── Persistence ───────────────────────────────────────────────────────────────

export function isActivated(): boolean {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return false
    const data = JSON.parse(raw) as { code: string; activatedAt: string }
    return !!data.code
  } catch {
    return false
  }
}

export function saveActivation(code: string, storeId?: number): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      code,
      storeId: storeId ?? null,
      activatedAt: new Date().toISOString(),
    }))
  } catch { /* ignore */ }
}

export function getLicenseInfo(): { code: string; storeId: string; activatedAt: string } | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const data = JSON.parse(raw) as { code: string; storeId?: number; activatedAt: string }
    return {
      code: data.code,
      storeId: data.storeId ? String(data.storeId).padStart(4, '0') : '0000',
      activatedAt: data.activatedAt,
    }
  } catch {
    return null
  }
}
